const [REDACTED];
function harness(response) {
  const calls = [], logs = [];
  const module = { exports: {} };
  const context = vm.createContext({ process: { env: { GEMINI_API_KEY: apiKey } }, console: { error(...args) { logs.push(args); } }, Error });
